import json
from base64 import b64encode
from typing import Optional

from taf.vran.vdu.enb.rest.client import HttpClient
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails
from taf.vran.vdu.enb.rest.exceptions import APIRequestError


class SECv1(HttpClient):
    def __init__(self, base_url: str, connection_details: ConnectionDetails) -> None:
        super().__init__(connection_details)
        self.base_url = base_url + "/api/sec/v1"

    def login(self, password: Optional[str] = None) -> dict:
        """
        Sends login request to the 4G vDU.

        :param str password: Password which will be used for login.
                             If None, the password from connection details will be used

        :returns: Response of the login request, for example:

            .. code-block:: python

                {
                   "UserId":10000,
                   "Type":"Bearer",
                   "Token":"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJjaXAiOiIxMC4xNTguMTAwLjEiLCJ",
                   "Expires":"2025-03-18T14:34:36+00:00",
                   "LastLogin":"2025-03-18T13:59:16+00:00",
                   "LastFailedLogin":"2025-03-12T14:18:14+00:00",
                   "FailedLoginAttempts":"There is no failed login attempt yet",
                   "PasswordExpirationDate":"Password never expires",
                   "UserType":"local",
                   "ReadOnlyMode":false,
                   "Role":"systemUserAccessMode"
                }
        :rtype: dict
        """
        access_token = self._get_basic_access_token(
            username=self.username, password=password if password else self.password
        )
        headers = {
            "Authorization": f"Basic {access_token}",
            "Content-Type": "application/json",
            "accept": "application/json",
        }

        try:
            response = self.send_request(
                method="POST",
                endpoint="/login",
                headers=headers,
                data=json.dumps({"ReadOnlyMode": self.connection_details.read_only}),
                verify=False,
            )

            self.token_storage.access_token = response["Token"]
            self.token_storage.expires_at = response["Expires"]

            return response

        except APIRequestError as e:
            if e.status_code == 403:
                error_response = e.response.json()
                self.token_storage.access_token = error_response.get("Token")
                self.token_storage.expires_at = error_response.get("Expires")

                if not self.connection_details.update_expired_password:
                    return error_response

                raise e
            else:
                raise e

    def logout(self) -> None:
        """ Sends logout request to the 4G vDU. """
        self.send_request(method="POST", endpoint="/logout", headers=self.headers.get(accept="any"))
        self.token_storage.remove_instance(connection_id=self.connection_details.connection_id)

    def get_token_info(self, timeout: Optional[int] = None) -> dict:
        """
        Gets token information

        :param int timeout: timeout for request, for example 30. Defaults to None

        :returns: Response of the request, for example:

            .. code-block:: python

                {
                  "User": "user1",
                  "Expires": "Mon Oct 28 06:21:22 UTC 2019",
                  "LastLogin": "Fri Oct 25 06:22:34 UTC 2019 from 10.110.70.37 on APIGW",
                  "LastFailedLogin": "Mon Oct 28 05:21:22 UTC 2019 from 10.110.70.37 on APIGW",
                  "FailedLoginAttempts": "There were 3 failed login attempts since the last successful login",
                  "AdditionalText": "Warning: your password will expire in 2 days"
                }
        :rtype: dict
        """
        headers = {
            "Authorization": f"Bearer {self.token_storage.access_token}",
            "Content-Type": "application/json",
            "accept": "application/json",
        }
        response = self.send_request(method="GET", endpoint="/token-info", headers=headers, timeout=timeout)

        return response

    @staticmethod
    def _get_basic_access_token(username: str = "Nemuadmin", password: str = "Nokia@123") -> str:
        basic_auth_token = "{username}:{password}"
        return b64encode(
            basic_auth_token.format(username=username, password=password).encode(
                encoding="utf-8"
            )
        ).decode()
